const tabId = 730410078;

const sitemapDates = await browserjs(tabId, async () => {
  const res = await fetch('/sitemap.xml');
  const text = await res.text();

  // Let's parse url tags
  const urls = [];
  const urlRegex = /<url>([\s\S]*?)<\/url>/g;
  let match;
  while ((match = urlRegex.exec(text)) !== null) {
    const block = match[1];
    const locMatch = block.match(/<loc>(.*?)<\/loc>/);
    const lastmodMatch = block.match(/<lastmod>(.*?)<\/lastmod>/);
    if (locMatch && locMatch[1].includes('/press-release/')) {
      urls.push({
        loc: locMatch[1],
        lastmod: lastmodMatch ? lastmodMatch[1] : null
      });
    }
  }
  return { count: urls.length, sample: urls.slice(0, 5) };
});

console.log('Sitemap dates:', sitemapDates);

const tabId = 730410078;

const allPrDates = await browserjs(tabId, async () => {
  const res = await fetch('/sitemap.xml');
  const text = await res.text();
  const urls = Array.from(text.matchAll(/<loc>(https:\/\/www\.instructure\.com\/press-release\/[^<]+)<\/loc>/g)).map(m => m[1]);

  async function getDate(url) {
    try {
      const r = await fetch(url);
      const html = await r.text();
      const doc = new DOMParser().parseFromString(html, 'text/html');
      const title = doc.querySelector('h1')?.innerText.trim() || '';
      const time = doc.querySelector('time')?.innerText.trim() || 
                    doc.querySelector('[class*="date"]')?.innerText.trim() || '';
      return { url, title, dateStr: time, timestamp: time ? new Date(time).getTime() : 0 };
    } catch (e) {
      return { url, error: e.message, timestamp: 0 };
    }
  }

  // Fetch in batches of 20
  const results = [];
  const batchSize = 20;
  for (let i = 0; i < urls.length; i += batchSize) {
    const batch = urls.slice(i, i + batchSize);
    const batchResults = await Promise.all(batch.map(getDate));
    results.push(...batchResults);
  }

  // Sort by timestamp
  results.sort((a, b) => a.timestamp - b.timestamp);
  return {
    total: results.length,
    earliest: results.slice(0, 10),
    invalidOrZero: results.filter(r => !r.timestamp || isNaN(r.timestamp))
  };
});

console.log('Total checked:', allPrDates.total);
