const tabId = 730410078;

const allUrlPatterns = await browserjs(tabId, async () => {
  const res = await fetch('/sitemap.xml');
  const text = await res.text();
  const urls = Array.from(text.matchAll(/<loc>([^<]+)<\/loc>/g)).map(m => m[1]);

  const categories = {};
  for (const u of urls) {
    const path = new URL(u).pathname;
    const firstSegment = path.split('/')[1] || 'root';
    categories[firstSegment] = (categories[firstSegment] || 0) + 1;
  }
  return { totalUrls: urls.length, categories };
});

