const nonDefaultCheck = await browserjs(tabId, async () => {
  const res = await fetch('/sitemap.xml');
  const text = await res.text();
  const allUrls = Array.from(text.matchAll(/<loc>([^<]+press-release\/[^<]+)<\/loc>/g)).map(m => m[1]);
  const nonDefault = allUrls.filter(u => !u.startsWith('https://www.instructure.com/press-release/'));

  async function getDate(url) {
    try {
      const r = await fetch(url);
      const html = await r.text();
      const doc = new DOMParser().parseFromString(html, 'text/html');
      const time = doc.querySelector('time')?.innerText.trim() || 
                    doc.querySelector('[class*="date"]')?.innerText.trim() || '';
      return { url, dateStr: time, timestamp: time ? new Date(time).getTime() : 0 };
    } catch (e) {
      return { url, error: e.message, timestamp: 0 };
    }
  }

  const results = [];
  const batchSize = 20;
  for (let i = 0; i < nonDefault.length; i += batchSize) {
    const batch = nonDefault.slice(i, i + batchSize);
    const batchResults = await Promise.all(batch.map(getDate));
    results.push(...batchResults);
  }

  results.sort((a, b) => a.timestamp - b.timestamp);
  return {
    total: results.length,
    earliest: results.slice(0, 5)
  };
});

